rule ransomware_detection {
  meta:
    description = "Detect ransomware attack"

  strings:
    -$ = "restore_tool.exe"

  condition:
    count(2 of any of {
      16 within $ => 16 within "C:\\Program Files\\restore_tool.exe" 
    })
}

